_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/6/35/\",\"title\":\"TEXT 35\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1975,\"bb\":568136,\"url_path\":\"/en/library/bg/6/34/devanagari/\",\"body_final\":\"चञ्चलं हि मन: कृष्ण प्रमाथि बलवद्दृढम् ।
तस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम् ॥ ३४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1976,\"bb\":1747,\"url_path\":\"/en/library/bg/6/34/b1747/\",\"body_value\":\"cañcalaṁ hi manaḥ kṛṣṇa
pramāthi balavad dṛḍham
tasyāhaṁ nigrahaṁ manye
vāyor iva su-duṣkaram\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1977,\"bb\":1748,\"url_path\":\"/en/library/bg/6/34/b1748/\",\"shadow_value\":\"cañcalam – flickering; hi – certainly; manaḥ – mind; kṛṣṇa – O Kṛṣṇa; pramāthi – agitating; bala-vat – strong; dṛḍham – obstinate; tasya – its; aham – I; nigraham – subduing; manye – think; vāyoḥ – of the wind; iva – like; su-duṣkaram – difficult.\",\"word_for_word_value\":[{\"word\":\"cañcalam\",\"translation\":\"flickering\"},{\"word\":\"hi\",\"translation\":\"certainly\"},{\"word\":\"manaḥ\",\"translation\":\"mind\"},{\"word\":\"kṛṣṇa\",\"translation\":\"O Kṛṣṇa\"},{\"word\":\"pramāthi\",\"translation\":\"agitating\"},{\"word\":\"bala-vat\",\"translation\":\"strong\"},{\"word\":\"dṛḍham\",\"translation\":\"obstinate\"},{\"word\":\"tasya\",\"translation\":\"its\"},{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"nigraham\",\"translation\":\"subduing\"},{\"word\":\"manye\",\"translation\":\"think\"},{\"word\":\"vāyoḥ\",\"translation\":\"of the wind\"},{\"word\":\"iva\",\"translation\":\"like\"},{\"word\":\"su-duṣkaram\",\"translation\":\"difficult\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1978,\"bb\":1749,\"url_path\":\"/en/library/bg/6/34/b1749/\",\"body_value\":\"The mind is restless, turbulent, obstinate and very strong, O Kṛṣṇa, and to subdue it, I think, is more difficult than controlling the wind.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1979,\"bb\":1750,\"url_path\":\"/en/library/bg/6/34/b1750/\",\"body_value\":\"The mind is so strong and obstinate that it sometimes overcomes the intelligence, although the mind is supposed to be subservient to the intelligence. For a man in the practical world who has to fight so many opposing elements, it is certainly very difficult to control the mind. Artificially, one may establish a mental equilibrium toward both friend and enemy, but ultimately no worldly man can do so, for this is more difficult than controlling the raging wind. In the Vedic literature (Kaṭha Upaniṣad 1.3.3–4) it is said:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1980,\"bb\":1751,\"url_path\":\"/en/library/bg/6/34/b1751/\",\"body_value\":\"ātmānaṁ rathinaṁ viddhi
śarīraṁ ratham eva ca
buddhiṁ tu sārathiṁ viddhi
manaḥ pragraham eva ca\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1981,\"bb\":1752,\"url_path\":\"/en/library/bg/6/34/b1752/\",\"body_value\":\"indriyāṇi hayān āhur
