ch/synonyms/?original=kaunteya\",\"children\":[\"$\",\"em\",null,{\"children\":\"kaunteya\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"O son of Kuntī\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-vairāgyeṇa\",{\"href\":\"/en/search/synonyms/?original=vairāgyeṇa\",\"children\":[\"$\",\"em\",null,{\"children\":\"vairāgyeṇa\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"by detachment\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ca\",{\"href\":\"/en/search/synonyms/?original=ca\",\"children\":[\"$\",\"em\",null,{\"children\":\"ca\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"also\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-gṛhyate\",{\"href\":\"/en/search/synonyms/?original=gṛhyate\",\"children\":[\"$\",\"em\",null,{\"children\":\"gṛhyate\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"can be so controlled\"}}],\".\"]}]]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"1983-translation,1983-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-1987\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"Lord Śrī Kṛṣṇa said: O mighty-armed son of Kuntī, it is undoubtedly very difficult to curb the restless mind, but it is possible by suitable practice and by detachment.\"}}]}]}]]]}]\n32:T7dc,"])self.__next_f.push([1,"The difficulty of controlling the obstinate mind, as expressed by Arjuna, is accepted by the Personality of Godhead. But at the same time He suggests that by practice and detachment it is possible. What is that practice? In the present age no one can observe the strict rules and regulations of placing oneself in a sacred place, focusing the mind on the Supersoul, restraining the senses and mind, observing celibacy, remaining alone, etc. By the practice of Kṛṣṇa consciousness, however, one engages in nine types of devotional service to the Lord. The first and foremost of such devotional engagements is hearing about Kṛṣṇa. This is a very powerful transcendental method for purging the mind of all misgivings. The more one hears about Kṛṣṇa, the more one becomes enlightened and detached from everything that draws the mind away from Kṛṣṇa. By detaching the mind from activities not devoted to the Lord, one can very easily learn vairāgya. Vairāgya means detachment from matter and engagement of the mind in spirit. Impersonal spiritual detachment is more difficult than attaching the mind to the activities of Kṛṣṇa. This is practical because by hearing about Kṛṣṇa one becomes automatically attached to the Supreme Spirit. This attachment is called pareśānubhava, spiritual satisfaction. It is just like the feeling of satisfaction a hungry man has for every morsel of food he eats. The more one eats while hungry, the more one feels satisfaction and strength. Similarly, by discharge of devotional service one feels transcendental satisfaction as the mind becomes detached from material objectives. It is something like curing a disease by expert treatment and appropriate diet. Hearing of the transcendental activities of Lord Kṛṣṇa is therefore expert treatment for the mad mind, and eating the foodstuff offered to Kṛṣṇa is the appropriate diet for the suffering patient. This treatment is the process of Kṛṣṇa consciousness."])self.__next_f.push([1,"2f:[\"$\",\"div\",\"1983-purport,1983-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L2a\",\"child-1988\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$32\"}}]}]]]}]\n33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"27:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"href\":\"https://t.me/online_vedabase\",\"className\":\"text-vb-normal-text hover:text-vb-normal-text/60\",\"alt\":\"Vedabase Telegram\",\"aria-label\":\"Vedabase T